import { View } from 'react-native';

import { cn, getInitials } from '@/lib/utils';

import { AppImage } from './image';
import { Text } from './text';

export interface AvatarProps {
  uri?: string | null;
  name?: string | null;
  size?: number;
  className?: string;
}

export function Avatar({ uri, name, size = 44, className }: AvatarProps) {
  return (
    <View
      style={{ width: size, height: size, borderRadius: size / 2 }}
      className={cn('items-center justify-center overflow-hidden bg-secondary', className)}
    >
      {uri ? (
        <AppImage
          source={{ uri }}
          style={{ width: size, height: size }}
          contentFit="cover"
          recyclingKey={uri}
        />
      ) : (
        <Text className="font-semibold text-secondary-foreground">{getInitials(name)}</Text>
      )}
    </View>
  );
}
